package main

import "fmt"

func fun(x, a, b, c int, count *int) {
	if a != x || b != x || c != x {
		if c != x {
			if a+b > x {
				c = x
			} else {
				c = a + b - 1
			}
			*count++
		}
		fun(x, c, a, b, count)
	}
}

func main() {
	var x, y int
	fmt.Scan(&x, &y)
	count := 0
	fun(x, y, y, y, &count)
	fmt.Println(count)
}

